    /// withdraws and posts a `.bin` still on disk the same way, while current.
    @discardableResult
    static func peaks(
        for media: MediaSnapshot, url: URL, stamp: CacheStamp?, into cacheDir: URL,
        pass: CachePass? = nil
    ) async -> Bool {
        guard media.hasAudio, media.duration > 0 else {
            if pass?.isCurrent() ?? true, clearPeaks(for: media.id, in: cacheDir) {
                postCacheChange(media: media.id, kind: peaksKind)
            }
            return true
        }
        if peaksAreCurrent(for: media, stamp: stamp, in: cacheDir) { return true }
        guard pass?.isCurrent() ?? true else { return false }
        if clearPeaks(for: media.id, in: cacheDir) {
            postCacheChange(media: media.id, kind: peaksKind)
        }
        let asset = AVURLAsset(url: url)
        guard let track = (try? await asset.loadTracks(withMediaType: .audio))?.first else {
            return false
        }
        guard let trackRange = try? await track.load(.timeRange),
            let segments = try? await track.load(.segments),
            let expected = expectedPeaksRanges(trackRange: trackRange, segments: segments)
        else { return false }
        return await onCacheLane {
            writePeaks(for: media, asset: asset, track: track, expectedRanges: expected,
                       stamp: stamp, into: cacheDir, pass: pass)
        }
    }

    // MARK: - Loudness

    /// Writes `cache/loudness/<id>.bin` (spec §11 AU-10, `MediaImporter+Loudness.swift`) after
    /// `peaks`, with `peaks`' head and answer: true when there is nothing to make, the cache is
    /// current, or it published; false otherwise, a superseded pass included.
    @discardableResult
    static func loudness(
        for media: MediaSnapshot, url: URL, stamp: CacheStamp?, into cacheDir: URL,
        pass: CachePass? = nil
    ) async -> Bool {
        guard loudnessPassNeeded(for: media, stamp: stamp, in: cacheDir, pass: pass) else {
            return true
        }
        guard pass?.isCurrent() != false else { return false }
        let asset = AVURLAsset(url: url)
        guard let track = (try? await asset.loadTracks(withMediaType: .audio))?.first,
            let trackRange = try? await track.load(.timeRange),
            let segments = try? await track.load(.segments),
            let expected = expectedPeaksRanges(trackRange: trackRange, segments: segments)
        else { return false }
        return await onCacheLane {
            writeLoudness(for: media, asset: asset, track: track, expectedRanges: expected,
                          stamp: stamp, into: cacheDir, pass: pass)
        }
    }

    // MARK: - Sync features

    /// Writes `cache/sync/<id>.bin` — Synchronize Audio's MFCC frames (spec
    /// §11 SY-11; `MediaImporter+SyncFeatures.swift` is the reader and the
    /// marker), run after `peaks` and before `speech`, and once more by
    /// `retryPeaks` after an attempt that lands the waveform. `speech`'s
    /// posture with no posts and no model: no audio clears what is on disk
    /// (while current); a current marker skips; a stale one is cleared first.
    static func syncFeatures(
        for media: MediaSnapshot, url: URL, stamp: CacheStamp?, into cacheDir: URL,
        pass: CachePass? = nil
    ) async {
        guard media.hasAudio, media.duration > 0 else {
            if pass?.isCurrent() ?? true { clearSyncFeatures(for: media.id, in: cacheDir) }
            return
        }
        guard !syncFeaturesAreCurrent(for: media, stamp: stamp, in: cacheDir) else { return }
        guard pass?.isCurrent() ?? true else { return }
        clearSyncFeatures(for: media.id, in: cacheDir)
        let asset = AVURLAsset(url: url)
        guard let track = (try? await asset.loadTracks(withMediaType: .audio))?.first else {
            return
        }
        await onCacheLane {
            writeSyncFeatures(for: media, asset: asset, track: track, stamp: stamp,
                              into: cacheDir, pass: pass)
        }
    }

    // MARK: - Speech

    /// Writes `cache/speech/<id>.bin` — road map 4's voice cache, run AFTER
    /// `peaks` in `generateCaches`'s order (never before it), so the `.bin`
    /// withdrawal at `peaks`' own head is never held behind a full-file
    /// decode and an inference pass.
    ///
    /// Skipped when `speechIsCurrent` (`MediaImporter+Speech.swift`'s head
    /// check) says the marker, the model and the chunk size all still agree,
    /// or when there is no audio at all, which while current withdraws and
    /// posts a `.bin` left on disk as below (#180). A stale cache is cleared
